import { CallExpressionShape, DurationShape, Plugin, Shape } from '@servicenow/sdk-build-core'
import { NowIdShape } from '../now-id-plugin'
import {
    CATEGORY_TABLE,
    METRIC_TABLE,
    DEFINITION_TABLE,
    DEFAULT_ASSESSMENT_DURATION,
    orderValue,
    categoryToShape,
    createCategoryRecord,
    validatePublishState,
    convertToNumber,
    baseAssessmentTypeProperties,
    baseAssessmentTypeToShapeProperties,
} from './assessment-utils'

const RISK_ASSESSMENT_CALLEE = 'RiskAssessment'

// change_risk_asmt_threshold.risk (choice). DB values match change_request.risk: 2=High, 3=Moderate, 4=Low.
const RISK_LEVEL_USER_TO_DB: { [key: string]: string } = {
    high: '2',
    moderate: '3',
    low: '4',
}
const RISK_LEVEL_DB_TO_USER: { [key: string]: string } = Object.fromEntries(
    Object.entries(RISK_LEVEL_USER_TO_DB).map(([k, v]) => [v, k])
)
const RISK_ASSESSMENT_TABLE = 'change_risk_asmt'
const THRESHOLD_TABLE = 'change_risk_asmt_threshold'
const DEFAULT_RISK_ASSESSMENT_TABLE = 'change_request'
const DEFAULT_RISK_EVALUATION_METHOD = 'risk_assessment'

export const RiskAssessmentPlugin = Plugin.create({
    name: 'RiskAssessmentPlugin',

    records: {
        [RISK_ASSESSMENT_TABLE]: {
            relationships: {
                [THRESHOLD_TABLE]: {
                    via: 'assessment',
                    descendant: true,
                },
                [CATEGORY_TABLE]: {
                    via: 'metric_type',
                    descendant: true,
                    relationships: {
                        [METRIC_TABLE]: {
                            via: 'category',
                            descendant: true,
                            relationships: {
                                [DEFINITION_TABLE]: {
                                    via: 'metric',
                                    descendant: true,
                                },
                            },
                        },
                    },
                },
            },

            async toShape(record, { descendants, transform }) {
                const categories = descendants.query(CATEGORY_TABLE).sort((a, b) => orderValue(a) - orderValue(b))
                const metrics = descendants.query(METRIC_TABLE)
                const definitions = descendants.query(DEFINITION_TABLE)
                const thresholds = descendants.query(THRESHOLD_TABLE)

                const categoryShapes = await Promise.all(
                    categories.map((category) => categoryToShape(category, metrics, definitions, transform))
                )

                const thresholdShapes = thresholds.map((threshold) =>
                    threshold.transform(({ $ }) => ({
                        $id: $.val(NowIdShape.from(threshold)),
                        risk: $.map((v) => {
                            const val = v.ifString()?.getValue()
                            return val ? (RISK_LEVEL_DB_TO_USER[val] ?? val) : undefined
                        }),
                        scoreGreaterThan: $.from('score_greater_than').map((v: Shape) => convertToNumber(v, 0)),
                    }))
                )

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: record,
                        callee: RISK_ASSESSMENT_CALLEE,
                        args: [
                            record.transform(({ $ }) => ({
                                ...baseAssessmentTypeToShapeProperties($, record),
                                assessmentDuration: $.from('duration')
                                    .map((v) => {
                                        const stringShape = v.ifString()?.ifNotEmpty()
                                        if (!stringShape) {
                                            return DurationShape.zero(record).getDuration()
                                        }
                                        return DurationShape.from(record, stringShape).getDuration()
                                    })
                                    .def(DurationShape.zero(record).getDuration()),
                                businessRule: $.from('business_rule').def(''),
                                deleteBusinessRule: $.from('delete_business_rule').def(''),
                                thresholds: $.val(thresholdShapes).def([]),
                                categories: $.val(categoryShapes).def([]),
                            })),
                        ],
                    }),
                }
            },
        },
    },

    shapes: [
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],
            async toRecord(callExpression, { factory, diagnostics }) {
                if (callExpression.getCallee() !== RISK_ASSESSMENT_CALLEE) {
                    return { success: false }
                }

                const arg = callExpression.getArgument(0).asObject()

                validatePublishState(arg, diagnostics)

                const typeRecord = await factory.createRecord({
                    source: callExpression,
                    table: RISK_ASSESSMENT_TABLE,
                    explicitId: arg.get('$id'),
                    properties: arg.transform(({ $ }) => ({
                        sys_domain: $.val('global'),
                        sys_domain_path: $.val('/'),
                        disable_ui_action: $.def(''),
                        enable_ui_action: $.def(''),
                        job: $.def(''),
                        user_field_business_rule: $.def(''),
                        business_rule: $.from('businessRule').def(''),
                        delete_business_rule: $.from('deleteBusinessRule').def(''),
                        ...baseAssessmentTypeProperties($),
                        table: $.def(DEFAULT_RISK_ASSESSMENT_TABLE),
                        // Risk assessments leave the scorecard filter table empty.
                        filter_table: $.def(''),
                        evaluation_method: $.val(DEFAULT_RISK_EVALUATION_METHOD),
                        duration: $.from('assessmentDuration')
                            .map((v) => {
                                if (!v.isDefined()) {
                                    return undefined
                                }
                                if (v.is(DurationShape)) {
                                    return v.as(DurationShape).toString().getValue()
                                }
                                const source = v.ifObject() ?? v.asString()
                                return DurationShape.from(v.getSource(), source).toString().getValue()
                            })
                            .def(DEFAULT_ASSESSMENT_DURATION),
                    })),
                })

                // Create threshold records
                const thresholdElements = arg.get('thresholds')?.ifArray()?.getElements() ?? []
                const thresholdRecords = await Promise.all(
                    thresholdElements.map(async (thresholdShape) => {
                        const threshold = thresholdShape.asObject()
                        return factory.createRecord({
                            source: callExpression,
                            table: THRESHOLD_TABLE,
                            explicitId: threshold.get('$id'),
                            properties: {
                                assessment: typeRecord.getId(),
                                risk: (() => {
                                    const val = threshold.get('risk').ifString()?.getValue()
                                    return val ? (RISK_LEVEL_USER_TO_DB[val] ?? val) : ''
                                })(),
                                score_greater_than: threshold.get('scoreGreaterThan').ifNumber()?.getValue() ?? 0,
                            },
                        })
                    })
                )

                // Create category records (same as Assessment)
                const categories = arg.get('categories')?.ifArray()?.getElements() ?? []
                const categoryRecords = await Promise.all(
                    categories.map((category) =>
                        createCategoryRecord(
                            category,
                            typeRecord,
                            Shape.from(callExpression, DEFAULT_RISK_ASSESSMENT_TABLE),
                            factory,
                            callExpression,
                            diagnostics
                        )
                    )
                )

                return {
                    success: true,
                    value: typeRecord.with(...thresholdRecords, ...categoryRecords),
                }
            },
        },
    ],
})
